-- Fictional expense scenarios: Krakow single 2025, family 2+1 2026, standalone wedding.
-- Prices are model assumptions; brands/events are public names, not real transactions.
-- V1/V2/V3 remain immutable. Refuse to replace any edited expense seed.
LOCK TABLE mf_expense_folder, mf_expense_category, mf_expense_tag, mf_expense_payment_source, mf_expense_item, mf_expense_item_tag, mf_expense_import_batch IN ACCESS EXCLUSIVE MODE;
CREATE TEMP TABLE expected_mf_expense_folder ON COMMIT DROP AS SELECT * FROM mf_expense_folder WITH NO DATA;
CREATE TEMP TABLE expected_mf_expense_category ON COMMIT DROP AS SELECT * FROM mf_expense_category WITH NO DATA;
CREATE TEMP TABLE expected_mf_expense_tag ON COMMIT DROP AS SELECT * FROM mf_expense_tag WITH NO DATA;
CREATE TEMP TABLE expected_mf_expense_payment_source ON COMMIT DROP AS SELECT * FROM mf_expense_payment_source WITH NO DATA;
CREATE TEMP TABLE expected_mf_expense_item ON COMMIT DROP AS SELECT * FROM mf_expense_item WITH NO DATA;
ALTER TABLE expected_mf_expense_item ALTER COLUMN counting_status SET DEFAULT 'included';
SELECT 1, CASE WHEN extract(year FROM demo_months.month) = 2025 THEN 3 ELSE 4 END,
       CASE WHEN expected_mf_expense_category.id = 4 THEN 2 ELSE 1 END,
       expected_mf_expense_category.id, 1, expected_mf_expense_category.name || ' — przykład', 'Fikcyjna pozycja demonstracyjna',
       CASE expected_mf_expense_category.id WHEN 1 THEN 2400 WHEN 2 THEN 1000 WHEN 3 THEN 450 WHEN 4 THEN 300 ELSE 85 END
         + CASE WHEN expected_mf_expense_category.id IN (2, 3, 4) THEN extract(month FROM demo_months.month)::int * 7 ELSE 0 END,
       demo_months.month::date, demo_months.month::date + 5, 'expense', '2026-11-13', '2026-11-13'
FROM expected_mf_expense_category
CROSS JOIN generate_series('2025-01-01'::date, '2026-11-01'::date, INTERVAL '1 month') AS demo_months(month);
VALUES (1, 4, 1, 1, 'Transfer własny — demo', 'Fikcyjny transfer wyłączony z wydatków', 1000, '2026-11-01', '2026-11-07', 'expense', 'excluded_internal_transfer', '2026-11-13', '2026-11-13');


DO $guard$
BEGIN
  IF current_database() NOT LIKE 'my-funds-demo%'
    OR (SELECT COUNT(*) FROM mf_user) <> 1
    OR NOT EXISTS (SELECT 1 FROM mf_user WHERE mf_user.id = 1 AND mf_user.username = 'demo')
    OR NOT EXISTS (SELECT 1 FROM mf_currency WHERE mf_currency.id = 1 AND mf_currency.code = 'PLN')
    OR NOT EXISTS (SELECT 1 FROM mf_demo_dataset_identity WHERE dataset_key = 'my-funds-fictional-demo' AND synthetic = true AND as_of_date = '2026-11-13')
    OR EXISTS (SELECT 1 FROM mf_expense_import_batch)
    OR EXISTS (SELECT to_jsonb(mf_expense_folder) FROM mf_expense_folder EXCEPT ALL SELECT to_jsonb(expected_mf_expense_folder) FROM expected_mf_expense_folder)
    OR EXISTS (SELECT to_jsonb(expected_mf_expense_folder) FROM expected_mf_expense_folder EXCEPT ALL SELECT to_jsonb(mf_expense_folder) FROM mf_expense_folder)
    OR EXISTS (SELECT to_jsonb(mf_expense_category) FROM mf_expense_category EXCEPT ALL SELECT to_jsonb(expected_mf_expense_category) FROM expected_mf_expense_category)
    OR EXISTS (SELECT to_jsonb(expected_mf_expense_category) FROM expected_mf_expense_category EXCEPT ALL SELECT to_jsonb(mf_expense_category) FROM mf_expense_category)
    OR EXISTS (SELECT to_jsonb(mf_expense_tag) FROM mf_expense_tag EXCEPT ALL SELECT to_jsonb(expected_mf_expense_tag) FROM expected_mf_expense_tag)
    OR EXISTS (SELECT to_jsonb(expected_mf_expense_tag) FROM expected_mf_expense_tag EXCEPT ALL SELECT to_jsonb(mf_expense_tag) FROM mf_expense_tag)
    OR EXISTS (SELECT to_jsonb(mf_expense_payment_source) FROM mf_expense_payment_source EXCEPT ALL SELECT to_jsonb(expected_mf_expense_payment_source) FROM expected_mf_expense_payment_source)
    OR EXISTS (SELECT to_jsonb(expected_mf_expense_payment_source) FROM expected_mf_expense_payment_source EXCEPT ALL SELECT to_jsonb(mf_expense_payment_source) FROM mf_expense_payment_source)
    OR EXISTS (SELECT to_jsonb(mf_expense_item) - 'id' FROM mf_expense_item EXCEPT ALL SELECT to_jsonb(expected_mf_expense_item) - 'id' FROM expected_mf_expense_item)
    OR EXISTS (SELECT to_jsonb(expected_mf_expense_item) - 'id' FROM expected_mf_expense_item EXCEPT ALL SELECT to_jsonb(mf_expense_item) - 'id' FROM mf_expense_item)
    OR EXISTS (
      SELECT mf_expense_item_tag.expense_item_id, mf_expense_item_tag.tag_id FROM mf_expense_item_tag
      EXCEPT ALL
      SELECT mf_expense_item.id, CASE WHEN mf_expense_item.category_id IN (1, 5) THEN 1 ELSE 2 END
      FROM mf_expense_item WHERE mf_expense_item.counting_status = 'included'
    )
    OR EXISTS (
      SELECT mf_expense_item.id, CASE WHEN mf_expense_item.category_id IN (1, 5) THEN 1 ELSE 2 END
      FROM mf_expense_item WHERE mf_expense_item.counting_status = 'included'
      EXCEPT ALL SELECT mf_expense_item_tag.expense_item_id, mf_expense_item_tag.tag_id FROM mf_expense_item_tag
    )
  THEN
    RAISE EXCEPTION 'V4 refuses to replace edited expense data/configuration. Expected untouched fictional V2 expenses in the isolated demo database. Preserve edits and prepare a reviewed transition; do not delete volumes or repair Flyway.';
  END IF;
END;
$guard$;

DELETE FROM mf_expense_item_tag;
DELETE FROM mf_expense_item;
DELETE FROM mf_expense_folder;
DELETE FROM mf_expense_category;
DELETE FROM mf_expense_tag;
DELETE FROM mf_expense_payment_source;

CREATE TEMP TABLE demo_expense_tags (fingerprint varchar(64), tag_id integer) ON COMMIT DROP;
SELECT mf_expense_item.id, demo_expense_tags.tag_id FROM mf_expense_item
JOIN demo_expense_tags ON demo_expense_tags.fingerprint = mf_expense_item.source_fingerprint;
SELECT setval(pg_get_serial_sequence('mf_expense_folder', 'id'), (SELECT MAX(mf_expense_folder.id) FROM mf_expense_folder));
SELECT setval(pg_get_serial_sequence('mf_expense_category', 'id'), (SELECT MAX(mf_expense_category.id) FROM mf_expense_category));
SELECT setval(pg_get_serial_sequence('mf_expense_tag', 'id'), (SELECT MAX(mf_expense_tag.id) FROM mf_expense_tag));
SELECT setval(pg_get_serial_sequence('mf_expense_payment_source', 'id'), (SELECT MAX(mf_expense_payment_source.id) FROM mf_expense_payment_source));
SELECT setval(pg_get_serial_sequence('mf_expense_item', 'id'), (SELECT MAX(mf_expense_item.id) FROM mf_expense_item));
